export async function checkLiveHistogramLanguage({call,evaluate,settle}) {
  const dir=process.env.LAYER_TEST_ARTIFACTS||'artifacts/localization-expansion/web';await mkdir(dir,{recursive:true});
  const scope=histogramJourney({evaluate,settle});
  const tags=await evaluate('layerApp.app.bootstrap_view().shipped_tags'),expected={};
  for(const tag of tags){const source=await readFile(new URL(`../../assets/locales/${tag}/settings.ftl`,import.meta.url),'utf8');expected[tag]=source.split('\n').find(line=>line.startsWith('settings-green = ')).slice('settings-green = '.length);}
  const wait=condition=>evaluate(`new Promise((resolve,reject)=>{const end=performance.now()+30000;function poll(){if(${condition})resolve(true);else if(performance.now()>end)reject(Error('Histogram language timeout'));else setTimeout(poll,20);}poll();})`);
  const restore=async tag=>{await evaluate(`layerApp.dispatch({type:'restore_saved_settings',saved:JSON.stringify({...layerApp.state().settings,language:{Explicit:${JSON.stringify(tag)}}})})`);await wait(`!layerApp.app.language_pending()&&document.documentElement.lang===${JSON.stringify(tag)}`);await settle();};
  await restore('en');await evaluate('layerApp.dispatch({type:"invoke",command:"fit_canvas"});layerApp.dispatch({type:"invoke",command:"pen"});layerApp.dispatch({type:"set_color",rgba:[.45,.45,.45,1]});layerApp.dispatch({type:"set_brush_size",value:100});');await settle();await wait('layerApp.app.brush_ready()');
  const point=await evaluate('(()=>{const r=layerApp.canvas.getBoundingClientRect();return{x:r.x+r.width/2-30,y:r.y+r.height/2};})()');for(const[type,dx,buttons]of[['mousePressed',0,1],['mouseMoved',60,1],['mouseReleased',60,0]]){await call('Input.dispatchMouseEvent',{type,x:point.x+dx,y:point.y,button:'left',buttons,clickCount:1,pointerType:'pen',force:buttons?1:0});await settle();}
  const baseline=await scope.exact();
  await evaluate(`window.histogramLocaleRoot=document.querySelector('[data-scope="histogram"]');window.histogramLocaleSelect=histogramLocaleRoot.querySelector('[data-scope-control="channel"]');window.histogramLocaleLog=histogramLocaleRoot.querySelector('[data-scope-control="log"]');histogramLocaleSelect.value='2';histogramLocaleSelect.dispatchEvent(new Event('change',{bubbles:true}));histogramLocaleSelect.focus();window.histogramLocaleEpoch=String(layerApp.state().document_file.epoch);window.histogramLocaleRevision=String(layerApp.state().document_file.revision);window.histogramLocaleCanvas=histogramLocaleRoot.querySelector('[data-scope-control="chart"]');`);await settle();
  for(const theme of ['light','dark']){
    await restore('en');await evaluate(`layerApp.dispatch({type:'set_theme',theme:${JSON.stringify(theme)}})`);await settle();
    const log=await evaluate('histogramLocaleLog.checked');
    await evaluate('window.histogramLocalePixels=Array.from(histogramLocaleCanvas.getContext("2d").getImageData(0,0,histogramLocaleCanvas.width,histogramLocaleCanvas.height).data)');
    assert.ok(await evaluate('histogramLocalePixels.some((v,i)=>i%4===3&&v>0)'),'Actual shared histogram graph renders');
    for(const tag of tags){
      await restore(tag);assert.deepEqual(await scope.exact(),baseline,`${tag} retained exact Visible data`);
      const view=await evaluate(`({same:histogramLocaleRoot===document.querySelector('[data-scope="histogram"]')&&histogramLocaleSelect===histogramLocaleRoot.querySelector('[data-scope-control="channel"]')&&histogramLocaleLog===histogramLocaleRoot.querySelector('[data-scope-control="log"]'),option:histogramLocaleSelect.options[2].textContent,value:histogramLocaleSelect.value,log:histogramLocaleLog.checked,focused:document.activeElement===histogramLocaleSelect,help:histogramLocaleCanvas.title,expectedHelp:[layerApp.state().histogram.description,layerApp.state().histogram.range].filter(Boolean).join('\\n'),status:histogramLocaleRoot.querySelector('[data-scope-control="status"]').textContent,expectedStatus:layerApp.state().histogram.status,sameDocument:String(layerApp.state().document_file.epoch)===histogramLocaleEpoch&&String(layerApp.state().document_file.revision)===histogramLocaleRevision})`);
      assert.ok(view.same&&view.focused&&view.sameDocument,`${tag} retained native controls, focus and source owner`);assert.equal(view.option,expected[tag]);assert.equal(view.value,'2');assert.equal(view.log,log);assert.equal(view.help,view.expectedHelp);assert.equal(view.status,view.expectedStatus);
      assert.ok(await evaluate('histogramLocaleCanvas===histogramLocaleRoot.querySelector("canvas")&&Array.from(histogramLocaleCanvas.getContext("2d").getImageData(0,0,histogramLocaleCanvas.width,histogramLocaleCanvas.height).data).every((v,i)=>v===histogramLocalePixels[i])'),`${tag} retained plot pixels within theme`);
      const shot=await call('Page.captureScreenshot',{format:'png'});await writeFile(`${dir}/histogram-${theme}-${tag}.png`,Buffer.from(shot.data,'base64'));
    }
  }
  await scope.hide();await restore('en');console.log('Histogram all-language shared scope retains controls, channel/log, focus, owner and Exact data in both themes');
}

