    await send({type:'form',action:{type:'new'}});await wait('!!document.querySelector(".workspace-form[open] input")');await evaluate(`window.workspaceLocaleEntry=document.querySelector('.workspace-form[open] input');workspaceLocaleEntry.focus();workspaceLocaleEntry.value='İı ไทย Tiếng Việt 雪🎨 {literal}';workspaceLocaleEntry.dispatchEvent(new Event('input',{bubbles:true}));workspaceLocaleEntry.setSelectionRange(2,7);window.workspaceLocaleDraft={value:workspaceLocaleEntry.value,start:workspaceLocaleEntry.selectionStart,end:workspaceLocaleEntry.selectionEnd};`);
